CREATE OR REPLACE FUNCTION public.create_product_with_opening_stock_v3(p_sku text, p_barcode text DEFAULT NULL::text, p_name_ar text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_brand_id uuid DEFAULT NULL::uuid, p_unit_id uuid DEFAULT NULL::uuid, p_purchase_unit_id uuid DEFAULT NULL::uuid, p_units_per_purchase_unit integer DEFAULT 1, p_default_purchase_price_in_minor_units bigint DEFAULT 0, p_cost_price_in_minor_units bigint DEFAULT 0, p_sale_price_in_minor_units bigint DEFAULT 0, p_wholesale_price_in_minor_units bigint DEFAULT 0, p_min_stock_level integer DEFAULT 0, p_max_stock_level integer DEFAULT NULL::integer, p_warehouse_id uuid DEFAULT NULL::uuid, p_opening_quantity integer DEFAULT 0, p_notes text DEFAULT 'رصيد افتتاحي عند إضافة المنتج'::text, p_image_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
  v_product_id UUID;
  v_image_url TEXT := NULLIF(BTRIM(p_image_url), '');
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إضافة المنتجات والأرصدة الافتتاحية'
  );

  v_result := public.create_product_with_opening_stock_v2(
    p_sku,
    p_barcode,
    p_name_ar,
    p_description,
    p_category_id,
    p_brand_id,
    p_unit_id,
    p_purchase_unit_id,
    p_units_per_purchase_unit,
    p_default_purchase_price_in_minor_units,
    p_cost_price_in_minor_units,
    p_sale_price_in_minor_units,
    p_wholesale_price_in_minor_units,
    p_min_stock_level,
    p_max_stock_level,
    p_warehouse_id,
    p_opening_quantity,
    p_notes
  );

  v_product_id := NULLIF(v_result->>'product_id', '')::UUID;
  IF v_product_id IS NULL THEN
    RAISE EXCEPTION 'لم يتم إرجاع معرف المنتج بعد إنشائه.';
  END IF;

  IF v_image_url IS NOT NULL THEN
    PERFORM public.set_product_primary_image(
      v_product_id,
      v_image_url
    );
  END IF;

  RETURN v_result || jsonb_build_object(
    'image_url',
    v_image_url
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_order_v2(p_supplier_id uuid, p_branch_id uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_expected_delivery_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_expected_header_discount_in_minor_units bigint DEFAULT 0, p_expected_supplier_freight_in_minor_units bigint DEFAULT 0, p_notes text DEFAULT NULL::text, p_internal_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_lines jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_canonical_lines JSONB;
  v_canonical_request JSONB;
  v_fingerprint TEXT;
  v_existing_operation public.business_operations%ROWTYPE;
  v_operation_id UUID := gen_random_uuid();
  v_purchase_order_id UUID := gen_random_uuid();
  v_purchase_order_number TEXT;
  v_result JSONB;
  v_line JSONB;
  v_component JSONB;
  v_po_item_id UUID;
  v_line_kind TEXT;
  v_commercial_quantity INTEGER;
  v_units_per_parcel INTEGER;
  v_ordered_base_quantity INTEGER;
  v_gross BIGINT;
  v_line_discount BIGINT;
  v_line_net BIGINT;
  v_line_net_total NUMERIC;
  v_total NUMERIC;
  v_product_id UUID;
  v_product public.products%ROWTYPE;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إنشاء أمر شراء - نموذج الطرود'
  );
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'PHASE2_AUTH_REQUIRED: يجب تسجيل الدخول.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 255 THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_IDEMPOTENCY_KEY_INVALID: مفتاح منع التكرار غير صالح.';
  END IF;
  IF p_expected_header_discount_in_minor_units < 0
    OR p_expected_supplier_freight_in_minor_units < 0
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_FINANCIAL_VALUE_INVALID: قيم أمر الشراء لا يمكن أن تكون سالبة.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.suppliers supplier
    WHERE supplier.id = p_supplier_id AND supplier.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_SUPPLIER_INVALID: المورد غير موجود أو غير نشط.';
  END IF;
  IF p_warehouse_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.warehouses warehouse
    WHERE warehouse.id = p_warehouse_id AND warehouse.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_WAREHOUSE_INVALID: المستودع غير موجود أو غير نشط.';
  END IF;
  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches branch
    WHERE branch.id = p_branch_id AND branch.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_BRANCH_INVALID: الفرع غير موجود أو غير نشط.';
  END IF;

  v_canonical_lines := public.phase2_canonicalize_receipt_lines_internal(p_lines);
  PERFORM public.phase2_validate_receipt_lines_internal(v_canonical_lines);
  SELECT COALESCE(SUM(
    (line->>'gross_amount_in_minor_units')::NUMERIC
    - (line->>'line_discount_in_minor_units')::NUMERIC
  ), 0)
  INTO v_line_net_total
  FROM jsonb_array_elements(v_canonical_lines) line;

  IF p_expected_header_discount_in_minor_units > v_line_net_total THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_purchase_order_header_discount_check',
      MESSAGE = 'PHASE2_HEADER_DISCOUNT_EXCEEDS_NET: الخصم المتوقع يتجاوز صافي أمر الشراء.';
  END IF;
  IF v_line_net_total = 0
    AND (p_expected_header_discount_in_minor_units > 0
      OR p_expected_supplier_freight_in_minor_units > 0)
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_purchase_order_zero_basis_check',
      MESSAGE = 'PHASE2_ZERO_ALLOCATION_BASIS: لا يمكن وضع خصم أو شحن متوقع على أساس صفري.';
  END IF;
  v_total := v_line_net_total
    - p_expected_header_discount_in_minor_units::NUMERIC
    + p_expected_supplier_freight_in_minor_units::NUMERIC;
  IF v_line_net_total > 9223372036854775807::NUMERIC
    OR v_total > 9223372036854775807::NUMERIC
  THEN
    RAISE EXCEPTION USING ERRCODE = '22003',
      MESSAGE = 'PHASE2_MONEY_OVERFLOW: قيمة أمر الشراء تتجاوز الحد المدعوم.';
  END IF;

  v_canonical_request := jsonb_build_object(
    'contract_version', 2,
    'operation_type', 'purchase_order_v2',
    'supplier_id', LOWER(p_supplier_id::TEXT),
    'branch_id', CASE WHEN p_branch_id IS NULL THEN NULL ELSE LOWER(p_branch_id::TEXT) END,
    'warehouse_id', CASE WHEN p_warehouse_id IS NULL THEN NULL ELSE LOWER(p_warehouse_id::TEXT) END,
    'expected_delivery_date', CASE WHEN p_expected_delivery_date IS NULL THEN NULL ELSE TO_CHAR(p_expected_delivery_date AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
    'expected_header_discount_in_minor_units', p_expected_header_discount_in_minor_units,
    'expected_supplier_freight_in_minor_units', p_expected_supplier_freight_in_minor_units,
    'notes', NULLIF(BTRIM(p_notes), ''),
    'internal_notes', NULLIF(BTRIM(p_internal_notes), ''),
    'lines', v_canonical_lines
  );
  v_fingerprint := public.phase2_request_fingerprint_internal(v_canonical_request);

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'purchase_order_v2:' || v_user_id::TEXT || ':' || v_key, 0
  ));
  SELECT * INTO v_existing_operation
  FROM public.business_operations operation
  WHERE operation.operation_type = 'purchase_order_v2'
    AND operation.initiated_by = v_user_id
    AND operation.idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing_operation.request_fingerprint IS NULL
      OR v_existing_operation.result_snapshot IS NULL
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'LEGACY_IDEMPOTENCY_IDENTITY_UNPROVEN: لا يمكن إثبات تطابق العملية التاريخية.';
    END IF;
    IF v_existing_operation.request_fingerprint IS DISTINCT FROM v_fingerprint THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'IDEMPOTENCY_CONFLICT: استُخدم المفتاح نفسه لطلب مختلف.';
    END IF;
    RETURN v_existing_operation.result_snapshot;
  END IF;

  LOOP
    v_purchase_order_number := 'PO-' || TO_CHAR(NOW(), 'YYYY') || '-'
      || LPAD(FLOOR(100000 + RANDOM() * 900000)::BIGINT::TEXT, 6, '0');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.purchase_orders purchase_order
      WHERE purchase_order.purchase_order_number = v_purchase_order_number
    );
  END LOOP;

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'operation_id', v_operation_id,
    'purchase_order_id', v_purchase_order_id,
    'purchase_order_number', v_purchase_order_number,
    'expected_total_in_minor_units', v_total::BIGINT
  );
  INSERT INTO public.business_operations (
    id, operation_type, idempotency_key, request_fingerprint,
    initiated_by, result_snapshot, completed_at
  ) VALUES (
    v_operation_id, 'purchase_order_v2', v_key, v_fingerprint,
    v_user_id, v_result, NOW()
  );
  INSERT INTO public.purchase_orders (
    id, purchase_order_number, supplier_id, branch_id, warehouse_id,
    status, order_date, expected_delivery_date, subtotal_in_minor_units,
    discount_in_minor_units, delivery_fee_in_minor_units,
    total_in_minor_units, amount_paid_in_minor_units,
    notes, internal_notes, created_by, operation_id
  ) VALUES (
    v_purchase_order_id, v_purchase_order_number, p_supplier_id,
    p_branch_id, p_warehouse_id, 'draft', NOW(), p_expected_delivery_date,
    v_line_net_total::BIGINT, p_expected_header_discount_in_minor_units,
    p_expected_supplier_freight_in_minor_units, v_total::BIGINT, 0,
    NULLIF(BTRIM(p_notes), ''), NULLIF(BTRIM(p_internal_notes), ''),
    v_user_id, v_operation_id
  );

  FOR v_line IN SELECT * FROM jsonb_array_elements(v_canonical_lines)
  LOOP
    v_po_item_id := gen_random_uuid();
    v_line_kind := v_line->>'line_kind';
    v_commercial_quantity := (v_line->>'commercial_quantity')::INTEGER;
    v_units_per_parcel := NULLIF(v_line->>'units_per_parcel', '')::INTEGER;
    v_ordered_base_quantity := (
      SELECT SUM((component->>'base_quantity')::INTEGER)
      FROM jsonb_array_elements(v_line->'components') component
    );
    v_gross := (v_line->>'gross_amount_in_minor_units')::BIGINT;
    v_line_discount := (v_line->>'line_discount_in_minor_units')::BIGINT;
    v_line_net := v_gross - v_line_discount;
    IF v_line_kind = 'base_unit' THEN
      v_product_id := (v_line->'components'->0->>'product_id')::UUID;
    ELSE
      v_product_id := (v_line->>'family_product_id')::UUID;
    END IF;

    INSERT INTO public.purchase_order_items (
      id, purchase_order_id, product_id, ordered_quantity,
      received_quantity, purchase_price_in_minor_units,
      discount_in_minor_units, line_total_in_minor_units,
      commercial_line_kind, family_product_id, parcel_configuration_id,
      configuration_revision, base_unit_name_snapshot,
      parcel_unit_name_snapshot, parcel_quantity, client_line_id,
      units_per_parcel_snapshot, received_parcel_quantity,
      commercial_quantity_snapshot, gross_amount_snapshot_in_minor_units,
      line_discount_snapshot_in_minor_units, line_net_snapshot_in_minor_units
    ) VALUES (
      v_po_item_id, v_purchase_order_id, v_product_id,
      v_ordered_base_quantity, 0,
      ROUND(v_gross::NUMERIC / v_ordered_base_quantity)::BIGINT,
      v_line_discount, v_line_net, v_line_kind,
      NULLIF(v_line->>'family_product_id', '')::UUID,
      NULLIF(v_line->>'parcel_configuration_id', '')::UUID,
      NULLIF(v_line->>'configuration_revision', '')::INTEGER,
      v_line->>'base_unit_name', NULLIF(v_line->>'parcel_unit_name', ''),
      CASE WHEN v_line_kind = 'configurable_parcel' THEN v_commercial_quantity END,
      (v_line->>'client_line_id')::UUID, v_units_per_parcel, 0,
      v_commercial_quantity, v_gross, v_line_discount, v_line_net
    );

    FOR v_component IN SELECT * FROM jsonb_array_elements(v_line->'components')
    LOOP
      v_product_id := (v_component->>'product_id')::UUID;
      SELECT * INTO v_product FROM public.products WHERE id = v_product_id;
      INSERT INTO public.purchase_order_item_components (
        purchase_order_item_id, product_id, expected_base_quantity,
        product_name_snapshot, sku_snapshot
      ) VALUES (
        v_po_item_id, v_product_id,
        (v_component->>'base_quantity')::INTEGER,
        v_product.name_ar, v_product.sku
      );
    END LOOP;
  END LOOP;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id, 'CREATE_PURCHASE_ORDER_V2', 'purchase_orders',
    v_purchase_order_id,
    jsonb_build_object(
      'operation_id', v_operation_id,
      'purchase_order_number', v_purchase_order_number,
      'expected_total_in_minor_units', v_total::BIGINT
    )
  );
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_customer_for_debt_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.payment_method = 'debt' AND NEW.customer_id IS NULL THEN
    RAISE EXCEPTION
      'البيع الآجل يتطلب عميلاً مسجلاً حتى يُحفظ الدين على حسابه.';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_product_flavor_inheritance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_master public.products%ROWTYPE;
BEGIN
  IF NEW.flavor_master_product_id IS NULL THEN
    IF NEW.is_flavor_master AND NEW.flavor_name_ar IS NOT NULL THEN
      RAISE EXCEPTION 'المنتج الأساسي لا يحمل اسم نكهة.';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.flavor_master_product_id = NEW.id THEN
    RAISE EXCEPTION 'لا يمكن ربط المنتج بنفسه كمنتج أساسي.';
  END IF;

  SELECT * INTO v_master
  FROM public.products
  WHERE id = NEW.flavor_master_product_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج الأساسي للنكهة غير موجود.';
  END IF;
  IF v_master.flavor_master_product_id IS NOT NULL THEN
    RAISE EXCEPTION 'لا يمكن إنشاء نكهة داخل نكهة أخرى.';
  END IF;

  NEW.flavor_name_ar := BTRIM(NEW.flavor_name_ar);
  NEW.is_flavor_master := false;
  NEW.category_id := v_master.category_id;
  NEW.brand_id := v_master.brand_id;
  NEW.unit_id := v_master.unit_id;
  NEW.purchase_unit_id := v_master.purchase_unit_id;
  NEW.units_per_purchase_unit := v_master.units_per_purchase_unit;
  NEW.default_purchase_price_in_minor_units :=
    v_master.default_purchase_price_in_minor_units;
  NEW.sale_unit_id := v_master.sale_unit_id;
  NEW.units_per_sale_unit := v_master.units_per_sale_unit;
  NEW.default_sale_price_in_minor_units :=
    v_master.default_sale_price_in_minor_units;
  IF TG_OP = 'INSERT' THEN
    NEW.cost_price_in_minor_units := v_master.cost_price_in_minor_units;
  END IF;
  NEW.sale_price_in_minor_units := v_master.sale_price_in_minor_units;
  NEW.wholesale_price_in_minor_units :=
    v_master.wholesale_price_in_minor_units;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_cash_shift_display_summary(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_shift public.cash_shifts%ROWTYPE; v_opened_by_name TEXT; v_actor_name TEXT;
BEGIN
  SELECT * INTO v_shift FROM public.cash_shifts WHERE id=p_shift_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'الوردية المحددة غير موجودة.'; END IF;
  IF v_shift.status NOT IN ('cancelled','reversed') THEN RETURN public.get_cash_shift_summary(p_shift_id); END IF;
  SELECT full_name INTO v_opened_by_name FROM public.profiles WHERE id=v_shift.opened_by;
  SELECT full_name INTO v_actor_name FROM public.profiles WHERE id=CASE WHEN v_shift.status='cancelled' THEN v_shift.cancelled_by ELSE v_shift.reversed_by END;
  RETURN jsonb_build_object('id',v_shift.id,'shiftNumber',v_shift.shift_number,'branchId',v_shift.branch_id,'cashierName',COALESCE(v_opened_by_name,'مستخدم النظام'),'startTime',v_shift.opened_at,'endTime',CASE WHEN v_shift.status='cancelled' THEN v_shift.cancelled_at ELSE v_shift.reversed_at END,'openingCashInMinorUnits',v_shift.opening_cash_in_minor_units,'cashSalesInMinorUnits',0,'cliqSalesInMinorUnits',0,'cardSalesInMinorUnits',0,'cashReceiptsInMinorUnits',0,'cliqReceiptsInMinorUnits',0,'cashSupplierPaymentsInMinorUnits',0,'cliqSupplierPaymentsInMinorUnits',0,'cashExpensesInMinorUnits',0,'cliqExpensesInMinorUnits',0,'cashRefundsInMinorUnits',0,'cliqRefundsInMinorUnits',0,'expectedCashInMinorUnits',v_shift.opening_cash_in_minor_units,'actualCashInMinorUnits',NULL,'cashDiscrepancyInMinorUnits',NULL,'discrepancyReason',NULL,'status',v_shift.status,'managerSignOffBy',NULL,'cancelledByName',CASE WHEN v_shift.status='cancelled' THEN v_actor_name ELSE NULL END,'cancelledAt',v_shift.cancelled_at,'cancellationReason',v_shift.cancellation_reason,'reversedByName',CASE WHEN v_shift.status='reversed' THEN v_actor_name ELSE NULL END,'reversedAt',v_shift.reversed_at,'reversalReason',v_shift.reversal_reason,'reversalId',v_shift.reversal_id);
END; $function$

CREATE OR REPLACE FUNCTION public.get_cash_shift_summary(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_summary JSONB;
  v_shift_status TEXT;
  v_cash_refunds BIGINT := 0;
  v_cliq_refunds BIGINT := 0;
  v_cash_opening_receipts BIGINT := 0;
  v_cliq_opening_receipts BIGINT := 0;
  v_cash_opening_supplier BIGINT := 0;
  v_cliq_opening_supplier BIGINT := 0;
  v_withdrawn BIGINT := 0;
  v_returned BIGINT := 0;
  v_comp JSONB;
BEGIN
  v_summary := public._get_cash_shift_summary_before_return_events(p_shift_id);
  SELECT status INTO v_shift_status
  FROM public.cash_shifts
  WHERE id = p_shift_id;
  SELECT effect.withdrawn_in_minor_units, effect.returned_in_minor_units
  INTO v_withdrawn, v_returned
  FROM public.owner_withdrawal_shift_effect_internal(p_shift_id) effect;
  v_summary := v_summary || jsonb_build_object(
    'ownerWithdrawalsInMinorUnits', v_withdrawn,
    'ownerWithdrawalReturnsInMinorUnits', v_returned);
  IF v_shift_status IS DISTINCT FROM 'open' THEN RETURN v_summary; END IF;
  SELECT
    COALESCE(SUM(money_refund_amount_in_minor_units) FILTER (WHERE refund_method = 'cash'), 0),
    COALESCE(SUM(money_refund_amount_in_minor_units) FILTER (WHERE refund_method = 'cliq'), 0)
  INTO v_cash_refunds, v_cliq_refunds
  FROM public.sales_return_events
  WHERE cash_shift_id = p_shift_id
    AND settlement_status = 'settled'
    AND money_refund_amount_in_minor_units > 0;
  SELECT
    COALESCE(SUM(opening_amount_in_minor_units) FILTER (WHERE payment_method = 'cash'), 0),
    COALESCE(SUM(opening_amount_in_minor_units) FILTER (WHERE payment_method = 'cliq'), 0)
  INTO v_cash_opening_receipts, v_cliq_opening_receipts
  FROM public.customer_collection_operations
  WHERE cash_shift_id = p_shift_id AND NOT is_reversed;
  SELECT
    COALESCE(SUM(payment.amount_in_minor_units) FILTER (WHERE payment.payment_method = 'cash'), 0),
    COALESCE(SUM(payment.amount_in_minor_units) FILTER (WHERE payment.payment_method = 'cliq'), 0)
  INTO v_cash_opening_supplier, v_cliq_opening_supplier
  FROM public.supplier_opening_payments link
  JOIN public.supplier_payments payment ON payment.id = link.supplier_payment_id
  WHERE link.cash_shift_id = p_shift_id AND NOT COALESCE(payment.is_reversed, false);
  v_comp:=public.cheque_shift_settlement_section_internal(p_shift_id);
  v_cash_opening_receipts:=v_cash_opening_receipts+(v_comp->>'cashReceiptsInMinorUnits')::BIGINT;
  v_cliq_opening_receipts:=v_cliq_opening_receipts+(v_comp->>'cliqReceiptsInMinorUnits')::BIGINT;
  v_cash_opening_supplier:=v_cash_opening_supplier+(v_comp->>'cashSupplierPaymentsInMinorUnits')::BIGINT;
  v_cliq_opening_supplier:=v_cliq_opening_supplier+(v_comp->>'cliqSupplierPaymentsInMinorUnits')::BIGINT;
  v_summary:=v_summary||jsonb_build_object('chequeCompensationSettlements',v_comp);
  v_summary := jsonb_set(v_summary, '{cashRefundsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cashRefundsInMinorUnits')::BIGINT, 0) + v_cash_refunds), true);
  v_summary := jsonb_set(v_summary, '{cliqRefundsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cliqRefundsInMinorUnits')::BIGINT, 0) + v_cliq_refunds), true);
  v_summary := jsonb_set(v_summary, '{cashReceiptsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cashReceiptsInMinorUnits')::BIGINT, 0) + v_cash_opening_receipts), true);
  v_summary := jsonb_set(v_summary, '{cliqReceiptsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cliqReceiptsInMinorUnits')::BIGINT, 0) + v_cliq_opening_receipts), true);
  v_summary := jsonb_set(v_summary, '{cashSupplierPaymentsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cashSupplierPaymentsInMinorUnits')::BIGINT, 0) + v_cash_opening_supplier), true);
  v_summary := jsonb_set(v_summary, '{cliqSupplierPaymentsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cliqSupplierPaymentsInMinorUnits')::BIGINT, 0) + v_cliq_opening_supplier), true);
  v_summary := v_summary || jsonb_build_object(
    'openingDebtCashReceiptsInMinorUnits', v_cash_opening_receipts-(v_comp->>'cashReceiptsInMinorUnits')::BIGINT,
    'openingDebtCliqReceiptsInMinorUnits', v_cliq_opening_receipts-(v_comp->>'cliqReceiptsInMinorUnits')::BIGINT,
    'openingSupplierCashPaymentsInMinorUnits', v_cash_opening_supplier-(v_comp->>'cashSupplierPaymentsInMinorUnits')::BIGINT,
    'openingSupplierCliqPaymentsInMinorUnits', v_cliq_opening_supplier-(v_comp->>'cliqSupplierPaymentsInMinorUnits')::BIGINT);
  RETURN jsonb_set(v_summary, '{expectedCashInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'expectedCashInMinorUnits')::BIGINT, 0)
      - v_cash_refunds + v_cash_opening_receipts - v_cash_opening_supplier
      - v_withdrawn + v_returned), true);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_customer_order_payment(p_order_id uuid, p_amount_in_minor_units bigint, p_payment_method text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID:=auth.uid();v_order RECORD;v_due BIGINT;v_new_paid BIGINT;
  v_payment_id UUID;v_payment_number TEXT;v_position RECORD;
BEGIN
  PERFORM public.cheque_assert_customer_payment_role_internal(p_order_id,p_payment_method);
  PERFORM public.phase4_lock_customer_order_context_internal(p_order_id,
    LOWER(COALESCE(p_payment_method,'')) IN ('cash','cliq'),false);
  SELECT * INTO v_position FROM public.phase42_order_financial_position_internal(p_order_id);
  IF COALESCE(p_amount_in_minor_units,0)<=0 OR p_amount_in_minor_units>v_position.outstanding_total_in_minor_units THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PHASE42_CUSTOMER_PAYMENT_EXCEEDS_EFFECTIVE_OUTSTANDING: Payment exceeds the Return-adjusted receivable.';
  END IF;
  IF p_amount_in_minor_units IS NULL OR p_amount_in_minor_units<=0 THEN RAISE EXCEPTION 'مبلغ الدفعة يجب أن يكون أكبر من صفر.';END IF;
  IF p_payment_method NOT IN ('cash','cliq','card','bank_transfer','cheque') THEN RAISE EXCEPTION 'طريقة الدفع غير معتمدة.';END IF;
  SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الطلب غير موجود.';END IF;
  IF v_order.status<>'completed' THEN RAISE EXCEPTION 'يمكن تسجيل الدفعة على طلب مكتمل فقط.';END IF;
  IF v_order.customer_id IS NULL THEN RAISE EXCEPTION 'الطلب غير مرتبط بعميل مسجل.';END IF;
  v_due:=GREATEST(v_order.total_in_minor_units-v_order.amount_paid_in_minor_units,0);
  IF v_due=0 THEN RAISE EXCEPTION 'الطلب مدفوع بالكامل.';END IF;
  IF p_amount_in_minor_units>v_due THEN
    RAISE EXCEPTION 'مبلغ الدفعة أكبر من المتبقي على الطلب (% د.أ).',TO_CHAR(v_due::NUMERIC/1000,'FM999999990.000');
  END IF;
  v_new_paid:=v_order.amount_paid_in_minor_units+p_amount_in_minor_units;
  v_payment_number:='CRV-'||TO_CHAR(NOW(),'YYYYMMDD')||'-'||LPAD(NEXTVAL('public.customer_payment_number_seq')::TEXT,6,'0');
  UPDATE public.orders SET amount_paid_in_minor_units=v_new_paid,
    payment_status=CASE WHEN v_new_paid>=total_in_minor_units THEN 'paid' ELSE 'partially_paid' END,
    updated_at=NOW() WHERE id=p_order_id;
  INSERT INTO public.customer_payments(payment_number,customer_id,order_id,amount_in_minor_units,payment_method,
    reference_number,notes,created_by)
  VALUES(v_payment_number,v_order.customer_id,p_order_id,p_amount_in_minor_units,p_payment_method,
    NULLIF(TRIM(p_reference_number),''),NULLIF(TRIM(p_notes),''),v_user_id) RETURNING id INTO v_payment_id;
  INSERT INTO public.audit_logs(user_id,action,entity_name,entity_id,details)
  VALUES(v_user_id,'RECORD_CUSTOMER_PAYMENT','customer_payments',v_payment_id,
    jsonb_build_object('payment_number',v_payment_number,'order_id',p_order_id,'order_number',v_order.order_number,
      'customer_id',v_order.customer_id,'amount_in_minor_units',p_amount_in_minor_units,
      'remaining_in_minor_units',v_order.total_in_minor_units-v_new_paid));
  RETURN jsonb_build_object('success',true,'payment_id',v_payment_id,'payment_number',v_payment_number,
    'order_id',p_order_id,'order_number',v_order.order_number,'amount_in_minor_units',p_amount_in_minor_units,
    'remaining_in_minor_units',v_order.total_in_minor_units-v_new_paid);
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_customer_order_payment(p_payment_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_id UUID;
  v_shift_id UUID;
  v_locked_order_id UUID;
  v_locked_shift_id UUID;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'عكس سند قبض عميل'
  );
  SELECT payment.order_id, payment.cash_shift_id
  INTO v_order_id, v_shift_id
  FROM public.customer_payments payment WHERE payment.id = p_payment_id;
  IF v_order_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Customer payment not found.';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('phase4-order|' || v_order_id::TEXT, 0));
  IF v_shift_id IS NOT NULL THEN
    PERFORM 1 FROM public.cash_shifts shift WHERE shift.id = v_shift_id FOR UPDATE;
  END IF;
  PERFORM 1 FROM public.orders customer_order WHERE customer_order.id = v_order_id FOR UPDATE;
  SELECT payment.order_id, payment.cash_shift_id
  INTO v_locked_order_id, v_locked_shift_id
  FROM public.customer_payments payment
  WHERE payment.id = p_payment_id FOR UPDATE;
  IF v_locked_order_id IS DISTINCT FROM v_order_id
    OR v_locked_shift_id IS DISTINCT FROM v_shift_id
  THEN
    RAISE EXCEPTION USING ERRCODE = '40001',
      MESSAGE = 'PHASE4_LOCK_PLAN_CHANGED_RETRY: Customer Payment relationship changed.';
  END IF;
  RETURN public._reverse_customer_order_payment_before_phase4_lock(
    p_payment_id, p_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_pos_sale(p_order_id uuid, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_order public.orders%ROWTYPE;
  v_shift public.cash_shifts%ROWTYPE;
  v_existing public.pos_sale_reversals%ROWTYPE;
  v_reason TEXT := NULLIF(BTRIM(p_reason), '');
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_item RECORD;
  v_balance_before INTEGER;
  v_balance_after INTEGER;
  v_reserved INTEGER;
  v_cogs BIGINT := 0;
  v_profit BIGINT := 0;
  v_quantity INTEGER := 0;
  v_effect JSONB;
  v_product_ids UUID[];
  v_reversal_id UUID := gen_random_uuid();
BEGIN
  v_user_id := public.assert_reversal_owner('عكس بيع نقطة بيع مكتمل');
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_ORDER_REQUIRED: بيع نقطة البيع غير محدد.';
  END IF;
  IF v_reason IS NULL OR CHAR_LENGTH(v_reason) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_REASON_INVALID: سبب العكس غير صالح.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_KEY_INVALID: مفتاح منع التكرار غير صالح.';
  END IF;

  PERFORM SET_CONFIG('lock_timeout', '3s', true);
  PERFORM SET_CONFIG('statement_timeout', '30s', true);

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_ORDER_NOT_FOUND: بيع نقطة البيع غير موجود.';
  END IF;
  IF v_order.cash_shift_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_SHIFT_MISSING: البيع غير مرتبط بورديّة صريحة.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'cash-shift-full-reversal:' || v_order.cash_shift_id::TEXT, 0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'pos-sale-reversal:' || p_order_id::TEXT, 0
  ));

  SELECT * INTO v_shift FROM public.cash_shifts
  WHERE id = v_order.cash_shift_id FOR UPDATE;
  IF NOT FOUND OR v_shift.status <> 'open' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_SHIFT_CLOSED: لا يمكن العكس على ورديّة غير مفتوحة.';
  END IF;

  SELECT * INTO v_existing FROM public.pos_sale_reversals
  WHERE requested_by = v_user_id AND idempotency_key = v_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.order_id <> p_order_id THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_POS_REVERSAL_IDEMPOTENCY_CONFLICT: مفتاح العكس مستخدم لبيع آخر.';
    END IF;
    RETURN JSONB_BUILD_OBJECT(
      'success', true,
      'idempotent', true,
      'reversal_id', v_existing.id,
      'order_id', v_existing.order_id,
      'cash_shift_id', v_existing.cash_shift_id,
      'actual_effect', v_existing.actual_effect
    );
  END IF;

  SELECT * INTO v_order FROM public.orders
  WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND OR v_order.source IS DISTINCT FROM 'pos'
    OR v_order.cash_shift_id <> v_shift.id
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_ORDER_INVALID: السجل ليس بيع POS قابلاً للعكس.';
  END IF;

  SELECT * INTO v_existing FROM public.pos_sale_reversals
  WHERE order_id = p_order_id FOR UPDATE;
  IF FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_DUPLICATE: تم عكس البيع مسبقًا.';
  END IF;
  IF v_order.status <> 'completed' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_ORDER_INVALID: البيع لم يعد مكتملًا قابلاً للعكس.';
  END IF;

  IF EXISTS (SELECT 1 FROM public.customer_payments payment
      WHERE payment.order_id = p_order_id)
    OR EXISTS (SELECT 1 FROM public.sales_returns return_row
      WHERE return_row.order_id = p_order_id)
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_DEPENDENCY_EXISTS: توجد دفعة أو مرتجع مرتبط بالبيع.';
  END IF;

  SELECT ARRAY_AGG(DISTINCT inventory_row.product_id
    ORDER BY inventory_row.product_id)
  INTO v_product_ids
  FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row;
  IF COALESCE(CARDINALITY(v_product_ids), 0) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_INVENTORY_IDENTITY_MISSING: لا توجد حقيقة مخزون قابلة للعكس.';
  END IF;

  -- Reuse the same SKU advisory/balance/product hierarchy as sale and receipt.
  PERFORM public.phase3_lock_inventory_products_internal(v_product_ids);

  -- Check chronology only after taking the shared product/balance lock hierarchy.
  -- This closes the race where a concurrent sale/receipt could commit between
  -- the chronology read and the inventory restoration.
  IF EXISTS (
    SELECT 1
    FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row
    JOIN public.inventory_movements movement
      ON movement.warehouse_id = v_order.warehouse_id
     AND movement.product_id = inventory_row.product_id
    WHERE movement.reference_id IS DISTINCT FROM p_order_id
      AND movement.created_at >= v_order.created_at
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_LATER_MOVEMENT: توجد حركة مخزون لاحقة على أحد أصناف البيع.';
  END IF;

  FOR v_item IN
    SELECT DISTINCT inventory_row.product_id
    FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row
    ORDER BY inventory_row.product_id
  LOOP
    SELECT balance.reserved_quantity INTO v_reserved
    FROM public.inventory_balances balance
    WHERE balance.warehouse_id = v_order.warehouse_id
      AND balance.product_id = v_item.product_id
    FOR UPDATE;
    IF NOT FOUND OR v_reserved <> 0 THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_POS_REVERSAL_INVENTORY_UNAVAILABLE: مخزون أحد الأصناف غير متاح أو محجوز.';
    END IF;
  END LOOP;

  SELECT
    COALESCE(SUM(item.cogs_in_minor_units), 0),
    COALESCE(SUM(item.profit_in_minor_units), 0)
  INTO v_cogs, v_profit
  FROM public.order_items item
  WHERE item.order_id = p_order_id;
  SELECT COALESCE(SUM(inventory_row.base_quantity), 0)::INTEGER
  INTO v_quantity
  FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row;

  v_effect := JSONB_BUILD_OBJECT(
    'payment_method', v_order.payment_method,
    'cash_in_minor_units', CASE WHEN v_order.payment_method = 'cash'
      THEN v_order.total_in_minor_units ELSE 0 END,
    'cliq_in_minor_units', CASE WHEN v_order.payment_method = 'cliq'
      THEN v_order.total_in_minor_units ELSE 0 END,
    'customer_receivable_in_minor_units', CASE WHEN v_order.payment_method = 'debt'
      THEN v_order.total_in_minor_units ELSE 0 END,
    'discount_in_minor_units', v_order.discount_in_minor_units,
    'cogs_in_minor_units', v_cogs,
    'profit_in_minor_units', v_profit,
    'restored_base_units', v_quantity
  );

  INSERT INTO public.pos_sale_reversals (
    id, order_id, cash_shift_id, requested_by, reason, idempotency_key,
    expected_effect, actual_effect
  ) VALUES (
    v_reversal_id, v_order.id, v_shift.id, v_user_id, v_reason, v_key,
    v_effect, v_effect
  );

  FOR v_item IN
    SELECT *
    FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row
    ORDER BY inventory_row.product_id,
      inventory_row.parcel_component_id NULLS FIRST,
      inventory_row.order_item_id
  LOOP
    SELECT balance.on_hand_quantity INTO v_balance_before
    FROM public.inventory_balances balance
    WHERE balance.warehouse_id = v_order.warehouse_id
      AND balance.product_id = v_item.product_id
    FOR UPDATE;
    v_balance_after := v_balance_before + v_item.base_quantity;
    UPDATE public.inventory_balances
    SET on_hand_quantity = v_balance_after, updated_at = NOW()
    WHERE warehouse_id = v_order.warehouse_id
      AND product_id = v_item.product_id;

    INSERT INTO public.inventory_movements (
      warehouse_id, product_id, movement_type, quantity,
      balance_before, balance_after, reference_type, reference_id,
      notes, created_by, operation_id, parcel_component_id
    ) VALUES (
      v_order.warehouse_id, v_item.product_id, 'return_in',
      v_item.base_quantity, v_balance_before, v_balance_after,
      'pos_sale_reversal', v_reversal_id,
      'عكس بيع نقطة البيع ' || v_order.order_number, v_user_id,
      v_item.operation_id, v_item.parcel_component_id
    );
  END LOOP;

  UPDATE public.orders
  SET status = 'cancelled', amount_paid_in_minor_units = 0,
    change_due_in_minor_units = 0, updated_at = NOW()
  WHERE id = v_order.id;

  INSERT INTO public.order_status_history (
    order_id, old_status, new_status, changed_by, notes
  ) VALUES (
    v_order.id, 'completed', 'cancelled', v_user_id,
    'عكس POS موثق: ' || v_reason
  );

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id, 'REVERSE_POS_SALE', 'pos_sale_reversals', v_reversal_id,
    JSONB_BUILD_OBJECT(
      'order_id', v_order.id,
      'order_number', v_order.order_number,
      'cash_shift_id', v_shift.id,
      'reason', v_reason,
      'effect', v_effect
    )
  );

  RETURN JSONB_BUILD_OBJECT(
    'success', true,
    'idempotent', false,
    'reversal_id', v_reversal_id,
    'order_id', v_order.id,
    'cash_shift_id', v_shift.id,
    'actual_effect', v_effect
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_product_primary_image(p_product_id uuid, p_image_url text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_image_id UUID;
  v_image_url TEXT := NULLIF(TRIM(p_image_url), '');
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'تحديث صورة المنتج'
  );

  IF p_product_id IS NULL THEN
    RAISE EXCEPTION 'معرف المنتج مطلوب.';
  END IF;
  IF v_image_url IS NULL THEN
    RAISE EXCEPTION 'رابط صورة المنتج مطلوب.';
  END IF;

  PERFORM 1
  FROM public.products
  WHERE id = p_product_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج المحدد غير موجود.';
  END IF;

  UPDATE public.product_images
  SET is_primary = false
  WHERE product_id = p_product_id
    AND is_primary = true;

  SELECT id
  INTO v_image_id
  FROM public.product_images
  WHERE product_id = p_product_id
    AND image_url = v_image_url
  ORDER BY created_at
  LIMIT 1;

  IF v_image_id IS NULL THEN
    INSERT INTO public.product_images (
      product_id,
      image_url,
      is_primary,
      display_order
    ) VALUES (
      p_product_id,
      v_image_url,
      true,
      1
    )
    RETURNING id INTO v_image_id;
  ELSE
    UPDATE public.product_images
    SET
      is_primary = true,
      display_order = 1
    WHERE id = v_image_id;
  END IF;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'SET_PRODUCT_PRIMARY_IMAGE',
    'products',
    p_product_id,
    jsonb_build_object(
      'product_image_id', v_image_id,
      'image_url', v_image_url
    )
  );

  RETURN v_image_id;
END;
$function$

